parameters.json:
[
  {
    "key": "hintStart",
    "en": "Hello! Someone on the island is waiting. Press Teach and show {b} what to do.",
    "fr": "Coucou ! Quelqu’un t’attend sur l’île. Appuie sur Apprendre et montre à {b} quoi faire."
  },
  {
    "key": "hintEmpty",
    "en": "Drive {b} yourself first: press Teach and use the arrows. {b} remembers every step.",
    "fr": "Conduis {b} toi-même d’abord : appuie sur Apprendre et utilise les flèches. {b} retient chaque pas."
  },
  {
    "key": "hintPattern",
    "en": "Look at the steps: the same little dance, over and over. What if {b} could \"do this {n} times\"?",
    "fr": "Regarde les pas : la même petite danse, encore et encore. Et si {b} pouvait « faire ça {n} fois » ?"
  },
  {
    "key": "hintMissed",
    "en": "{b} did {w} of {t}. Which one did {b} walk past?",
    "fr": "{b} en a fait {w} sur {t}. Lequel a-t-il raté ?"
  },
  {
    "key": "hintNotYet",
    "en": "Not quite yet. Play it with One step and watch each block.",
    "fr": "Pas tout à fait. Joue-le avec « Un pas » et regarde chaque bloc."
  },
  {
    "key": "hintBump",
    "en": "{b} bumped into something. Which step sent {b} the wrong way?",
    "fr": "{b} s’est cogné. Quel pas l’a envoyé du mauvais côté ?"
  },
  {
    "key": "hintWet",
    "en": "A puddle! {b} watered where there is no tulip. Where was {b} facing?",
    "fr": "Une flaque ! {b} a arrosé là où il n’y a pas de tulipe. Il regardait où ?"
  },
  {
    "key": "hintDone",
    "en": "Perfect! Could you do it with fewer blocks? A repeat counts as one.",
    "fr": "Parfait ! Tu peux le faire avec moins de blocs ? Un « répéter » compte pour un."
  },
  {
    "key": "hintDoneMany",
    "en": "It works, with {k} blocks. The same steps come back: a repeat could hold them.",
    "fr": "Ça marche, avec {k} blocs. Les mêmes pas reviennent : un « répéter » pourrait les tenir."
  },
  {
    "key": "hintPerfect",
    "en": "Perfect! Not one block too many.",
    "fr": "Parfait ! Pas un bloc de trop."
  },
  {
    "key": "hintFree",
    "en": "{b} did what you said. Try a new idea, or ask an islander.",
    "fr": "{b} a fait ce que tu as dit. Essaie une nouvelle idée, ou va voir un habitant."
  },
  {
    "key": "hintDry",
    "en": "The can is empty. Where is the pond?",
    "fr": "L’arrosoir est vide. Où est la mare ?"
  },
  {
    "key": "hintRockGone",
    "en": "Nothing left in that rock! {b} has the stones: where do they go?",
    "fr": "Plus rien dans ce rocher ! {b} a les pierres : où vont-elles ?"
  },
  {
    "key": "hintPredictMiss",
    "en": "You tapped one tile, {b} stopped on another. Follow the steps with your finger, one by one.",
    "fr": "Tu as touché une case, {b} s’est arrêté sur une autre. Suis les pas avec ton doigt, un par un."
  },
  {
    "key": "hintDriveReady",
    "en": "{b} still knows your steps. Press Play to watch them, or Teach to change them.",
    "fr": "{b} connaît toujours tes pas. Appuie sur Jouer pour les regarder, ou sur Apprendre pour les changer."
  },
  {
    "key": "oliveThinking",
    "en": "Olive is thinking…",
    "fr": "Olive réfléchit…"
  },
  {
    "key": "oliveResting",
    "en": "Olive is resting. Here is her written line.",
    "fr": "Olive se repose. Voici sa phrase écrite."
  },
  {
    "key": "oliveRung1",
    "en": "Olive said thank you through {b}. Run it twice: she never says it the same way.",
    "fr": "Olive a dit merci par la voix de {b}. Lance-le deux fois : elle ne le dit jamais pareil."
  },
  {
    "key": "oliveRung2",
    "en": "Olive read the note. Use “if Olive read…” to send {b} to the right row.",
    "fr": "Olive a lu le mot. Utilise « si Olive a lu… » pour envoyer {b} vers la bonne rangée."
  },
  {
    "key": "oliveRung3",
    "en": "Olive said whether the thing ahead is one. When she is wrong, ask 3 times and count the yeses.",
    "fr": "Olive a dit si ce qui est devant en est un. Quand elle se trompe, demande 3 fois et compte les oui."
  },
  {
    "key": "oliveResting1",
    "en": "Olive is resting, so {b} used her written thank-you.",
    "fr": "Olive se repose, alors {b} a pris son merci écrit."
  },
  {
    "key": "oliveResting2",
    "en": "Olive is resting, so {b} used her written answer to “read the note”.",
    "fr": "Olive se repose, alors {b} a pris sa réponse écrite à « lire le mot »."
  },
  {
    "key": "oliveResting3",
    "en": "Olive is resting, so {b} used her written answer to “is it a…?”.",
    "fr": "Olive se repose, alors {b} a pris sa réponse écrite à « est-ce un… ? »."
  },
  {
    "key": "iw1Loop",
    "en": "{b} is going round and round — is there a loop that never ends?",
    "fr": "{b} tourne en rond — y a-t-il une boucle qui ne s’arrête jamais ?"
  },
  {
    "key": "iw3NoCan",
    "en": "{b} needs the can in hand first. Where is it?",
    "fr": "{b} doit d’abord prendre l’arrosoir. Où est-il ?"
  },
  {
    "key": "iw3Job",
    "en": "{w} of {t} done. What is still waiting?",
    "fr": "{w} sur {t}, c’est fait. Qu’est-ce qui attend encore ?"
  },
  {
    "key": "iw3bTrick",
    "en": "The job is done! Now teach {b} the way the card asks — with its own block.",
    "fr": "Le travail est fait ! Maintenant, apprends à {b} comme la carte le demande — avec son bloc à elle."
  }
]
